WITH base_bal AS (    SELECT CTACTB,           SUM(CASE WHEN YEAR(REFERENCIA) = YEAR(DATE(:VAR_DATA_REF_DRE)) THEN VLRLANC ELSE 0 END) AS soma_ate_atu,           SUM(CASE WHEN YEAR(REFERENCIA) = YEAR(DATE_SUB(DATE(:VAR_DATA_REF_DRE), INTERVAL 1 YEAR)) THEN VLRLANC ELSE 0 END) AS soma_ate_ant    FROM IMP_BASE_BALANCETE    WHERE CODEMP = :VAR_EMPRESA_DRE      AND (CTACTB LIKE '3%' OR CTACTB LIKE '4%' OR CTACTB LIKE '5%')      AND (          YEAR(REFERENCIA) = YEAR(DATE(:VAR_DATA_REF_DRE)) OR          YEAR(REFERENCIA) = YEAR(DATE_SUB(DATE(:VAR_DATA_REF_DRE), INTERVAL 1 YEAR))      )    GROUP BY CTACTB)SELECT A.ORDEM AS HIERARQUIA, A.NOME_GRUPO AS DESCRICAO, A.COD_NOTA_EXPLICATIVA AS NOTA,       SUM(IFNULL(B.soma_ate_atu, 0) * C.SINAL) AS VALOR_ANO_ATUAL,       SUM(IFNULL(B.soma_ate_ant, 0) * C.SINAL) AS VALOR_ANO_ANTERIORFROM DET_DEMONSTRATIVO AINNER JOIN ESTR_DEMONSTRATIVOS E ON E.ID = A.ID_ESTR_DEMONSTRATIVOLEFT JOIN DET_DEMONSTRATIVO_REFERENCIA R ON R.ID_DET_DEMONSTRATIVO = A.IDLEFT JOIN DET_DEMONSTRATIVO_CTACTB C ON C.ID_DET_DEMONSTRATIVO_REFERENCIA = R.IDLEFT JOIN base_bal B ON B.CTACTB = C.PADRAO_CTACTBWHERE E.ID = 3GROUP BY A.ORDEM, A.NOME_GRUPO, A.COD_NOTA_EXPLICATIVAORDER BY A.ORDEM